                                if (isprint(CAST(unsigned char, c))) {
                                        /* Allow escaping of
                                         * ``relations'' */
                                        if (strchr("<>&^=!", c) == NULL
                                            && (m->type != FILE_REGEX ||
                                            strchr("[]().*?^$|{}", c)
                                            == NULL)) {
                                                file_magwarn(ms, "no "
                                                    "need to escape "
                                                    "`%c'", c);
                                        }
                                } else {
                                        file_magwarn(ms,
                                            "unknown escape sequence: "
                                            "\\%03o", c);
                                }
